import"./chunk-ZW5NV4UO.js";var e={en:{title:"Space and astronomy on Mastodon: who and what to follow",description:"Astronomers, astrophotographers, spaceflight fans and space YouTubers on Mastodon, plus the hashtags worth following. Read it all before you make an account.",heading:"Space and astronomy on Mastodon",listTitle:"Space and astronomy",intro:["Mastodon is full of people looking up: professional astronomers and planetary scientists, astrophotographers with backyard telescopes, launch watchers, observatories, and science writers who explain what the latest mission found.","Starting from an empty timeline is slow. This page gives you a head start: the hashtags people actually use, the people worth following, and a server where the space community gathers."],faq:[{q:"Do I need an account to read this?",a:"No. Every hashtag here opens in Mawkingbird without an account. To follow people and tags you need a Mastodon account on any server; mastodon.social is a fine first choice, and you can move later and keep your followers."},{q:"Is Mastodon a good place for space and astronomy?",a:"Yes. Many astronomers and space scientists moved to Mastodon, astrophotographers share their nights under #Astrophotography, and launches, eclipses and new telescope images get busy, knowledgeable threads. Conversations are slower than on Twitter and less driven by outrage."},{q:"How do I get onto this list?",a:"Post about space or astronomy, use the hashtags above, and let your profile be suggested to others (your server\u2019s Privacy and reach settings). The list is refreshed every month."}]},de:{title:"Weltraum und Astronomie auf Mastodon: wem du folgen kannst",description:"Astronominnen, Astrofotografen, Raumfahrt-Fans und Weltraum-YouTuber auf Mastodon, dazu die passenden Hashtags. Alles lesbar, bevor du ein Konto anlegst.",heading:"Weltraum und Astronomie auf Mastodon",listTitle:"Weltraum und Astronomie",intro:["Auf Mastodon schauen viele nach oben: Astronominnen und Planetenforscher, Astrofotografen mit Teleskop im Garten, Leute, die jeden Raketenstart verfolgen, Sternwarten und Wissenschaftsjournalisten, die erkl\xE4ren, was die neueste Mission gefunden hat.","Mit einer leeren Startseite anzufangen ist m\xFChsam. Diese Seite hilft dir beim Start: Hashtags, die wirklich benutzt werden, Leute, denen sich das Folgen lohnt, und ein Server, auf dem sich die Weltraum-Community trifft."],faq:[{q:"Brauche ich ein Konto, um mitzulesen?",a:"Nein. Jeder Hashtag hier \xF6ffnet sich in Mawkingbird ohne Konto. Um Leuten und Hashtags zu folgen, brauchst du ein Mastodon-Konto auf irgendeinem Server; mastodon.social ist ein guter Anfang, und du kannst sp\xE4ter umziehen und deine Follower mitnehmen."},{q:"Warum stehen hier englische Hashtags?",a:"Viele Gespr\xE4che \xFCber Astronomie und Raumfahrt laufen auf Mastodon unter englischen Hashtags, auch von Leuten, die auf Deutsch schreiben. Wir zeigen die aktivsten und dazu deutsche Hashtags wie #Astronomie und #Raumfahrt."},{q:"Wie komme ich auf diese Liste?",a:"Schreib \xFCber Weltraum oder Astronomie, benutze die Hashtags oben und erlaube in den Einstellungen deines Servers (Privatsph\xE4re und Reichweite), dass dein Profil anderen vorgeschlagen wird. Die Liste wird jeden Monat erneuert."}]},fr:{title:"Espace et astronomie sur Mastodon\xA0: qui et quoi suivre",description:"Astronomes, astrophotographes, passionn\xE9s de spatial et youtubeurs de l\u2019espace sur Mastodon, et les hashtags \xE0 suivre. Tout se lit avant de cr\xE9er un compte.",heading:"Espace et astronomie sur Mastodon",listTitle:"Espace et astronomie",intro:["Sur Mastodon, beaucoup de monde a la t\xEAte dans les \xE9toiles\xA0: astronomes et plan\xE9tologues, astrophotographes avec leur t\xE9lescope au jardin, fans de lancements, observatoires, et journalistes scientifiques qui expliquent ce que la derni\xE8re mission a d\xE9couvert.","Partir d\u2019un fil vide, c\u2019est long. Cette page te donne un coup de pouce\xA0: les hashtags vraiment utilis\xE9s, les personnes \xE0 suivre et un serveur o\xF9 se retrouve la communaut\xE9 de l\u2019espace."],faq:[{q:"Faut-il un compte pour lire tout \xE7a\u202F?",a:"Non. Chaque hashtag s\u2019ouvre dans Mawkingbird sans compte. Pour suivre des personnes et des hashtags, il te faut un compte Mastodon sur n\u2019importe quel serveur\xA0; mastodon.social est un bon d\xE9but, et tu pourras d\xE9m\xE9nager plus tard en gardant tes abonn\xE9s."},{q:"Pourquoi des hashtags en anglais\u202F?",a:"Une grande partie des conversations sur l\u2019astronomie et le spatial se tient sous des hashtags anglais, y compris chez des gens qui \xE9crivent en fran\xE7ais. On montre les plus actifs, avec les hashtags fran\xE7ais comme #Astronomie et #Espace."},{q:"Comment figurer sur cette liste\u202F?",a:"Publie sur l\u2019espace ou l\u2019astronomie, utilise les hashtags ci-dessus et autorise ton serveur \xE0 sugg\xE9rer ton profil (r\xE9glages de confidentialit\xE9 et de visibilit\xE9). La liste est mise \xE0 jour chaque mois."}]},es:{title:"Espacio y astronom\xEDa en Mastodon: a qui\xE9n y qu\xE9 seguir",description:"Astr\xF3nomos, astrofot\xF3grafos, fans de la exploraci\xF3n espacial y youtubers del espacio en Mastodon, y las etiquetas que conviene seguir. L\xE9elo sin crear cuenta.",heading:"Espacio y astronom\xEDa en Mastodon",listTitle:"Espacio y astronom\xEDa",intro:["En Mastodon hay mucha gente mirando al cielo: astr\xF3nomas y cient\xEDficos planetarios, astrofot\xF3grafos con su telescopio en el patio, quienes siguen cada lanzamiento, observatorios y divulgadores que explican lo que encontr\xF3 la \xFAltima misi\xF3n.","Empezar con un inicio vac\xEDo es lento. Esta p\xE1gina te da un empuj\xF3n: las etiquetas que de verdad se usan, las personas que vale la pena seguir y un servidor donde se re\xFAne la comunidad del espacio."],faq:[{q:"\xBFNecesito una cuenta para leer esto?",a:"No. Cada etiqueta se abre en Mawkingbird sin cuenta. Para seguir a personas y etiquetas necesitas una cuenta de Mastodon en cualquier servidor; mastodon.social es un buen comienzo, y puedes mudarte despu\xE9s sin perder a tus seguidores."},{q:"\xBFPor qu\xE9 hay etiquetas en ingl\xE9s?",a:"Muchas conversaciones sobre astronom\xEDa y el espacio usan etiquetas en ingl\xE9s, tambi\xE9n entre quienes escriben en espa\xF1ol. Mostramos las m\xE1s activas junto a etiquetas en espa\xF1ol como #Astronom\xEDa y #Espacio."},{q:"\xBFC\xF3mo entro en esta lista?",a:"Publica sobre el espacio o la astronom\xEDa, usa las etiquetas de arriba y permite que tu servidor sugiera tu perfil a otras personas (ajustes de privacidad y alcance). La lista se actualiza cada mes."}]},it:{title:"Spazio e astronomia su Mastodon: chi e cosa seguire",description:"Astronomi, astrofotografi, appassionati di spazio e youtuber su Mastodon, e gli hashtag da seguire. Puoi leggere tutto senza account.",heading:"Spazio e astronomia su Mastodon",listTitle:"Spazio e astronomia",intro:["Su Mastodon tante persone guardano in alto: astronome e planetologi, astrofotografi con il telescopio in giardino, chi segue ogni lancio, osservatori e divulgatori che spiegano cosa ha scoperto l\u2019ultima missione.","Partire da una home vuota \xE8 lento. Questa pagina ti d\xE0 una spinta: gli hashtag usati davvero, le persone da seguire e un server dove si ritrova la comunit\xE0 dello spazio."],faq:[{q:"Serve un account per leggere?",a:"No. Ogni hashtag si apre in Mawkingbird senza account. Per seguire persone e hashtag ti serve un account Mastodon su un server qualsiasi; mastodon.social va benissimo per iniziare, e puoi traslocare dopo portando con te i tuoi follower."},{q:"Perch\xE9 ci sono hashtag in inglese?",a:"Molte conversazioni su astronomia e spazio passano per hashtag inglesi, anche tra chi scrive in italiano. Mostriamo i pi\xF9 attivi insieme agli hashtag italiani da far crescere, come #Astronomia e #Spazio."},{q:"Come entro in questa lista?",a:"Scrivi di spazio o astronomia, usa gli hashtag qui sopra e permetti al tuo server di suggerire il tuo profilo ad altri (impostazioni di privacy e visibilit\xE0). La lista viene aggiornata ogni mese."}]},ja:{title:"Mastodon\uFF08\u30DE\u30B9\u30C8\u30C9\u30F3\uFF09\u306E\u5B87\u5B99\u30FB\u5929\u6587\uFF1A\u30D5\u30A9\u30ED\u30FC\u3057\u305F\u3044\u4EBA\u3068\u30BF\u30B0",description:"Mastodon\uFF08\u30DE\u30B9\u30C8\u30C9\u30F3\uFF09\u3067\u6D3B\u52D5\u3059\u308B\u5929\u6587\u5B66\u8005\u3001\u5929\u4F53\u5199\u771F\u5BB6\u3001\u5B87\u5B99\u958B\u767A\u30D5\u30A1\u30F3\u3001\u5B87\u5B99\u7CFB YouTuber \u3068\u3001\u30D5\u30A9\u30ED\u30FC\u3057\u305F\u3044\u30CF\u30C3\u30B7\u30E5\u30BF\u30B0\u3002\u30A2\u30AB\u30A6\u30F3\u30C8\u304C\u306A\u304F\u3066\u3082\u8AAD\u3081\u307E\u3059\u3002",heading:"Mastodon\uFF08\u30DE\u30B9\u30C8\u30C9\u30F3\uFF09\u306E\u5B87\u5B99\u30FB\u5929\u6587",listTitle:"\u5B87\u5B99\u30FB\u5929\u6587",intro:["Mastodon \u306B\u306F\u7A7A\u3092\u898B\u4E0A\u3052\u308B\u4EBA\u304C\u305F\u304F\u3055\u3093\u3044\u307E\u3059\u3002\u5929\u6587\u5B66\u8005\u3084\u60D1\u661F\u79D1\u5B66\u8005\u3001\u5EAD\u306E\u671B\u9060\u93E1\u3067\u661F\u3092\u64AE\u308B\u5929\u4F53\u5199\u771F\u5BB6\u3001\u30ED\u30B1\u30C3\u30C8\u306E\u6253\u3061\u4E0A\u3052\u3092\u8FFD\u3044\u304B\u3051\u308B\u4EBA\u3001\u5929\u6587\u53F0\u3001\u305D\u3057\u3066\u6700\u65B0\u306E\u63A2\u67FB\u3067\u4F55\u304C\u308F\u304B\u3063\u305F\u306E\u304B\u3092\u89E3\u8AAC\u3059\u308B\u30B5\u30A4\u30A8\u30F3\u30B9\u30E9\u30A4\u30BF\u30FC\u306A\u3069\u3067\u3059\u3002","\u4F55\u3082\u306A\u3044\u30DB\u30FC\u30E0\u304B\u3089\u59CB\u3081\u308B\u306E\u306F\u5927\u5909\u3067\u3059\u3002\u3053\u306E\u30DA\u30FC\u30B8\u3067\u306F\u3001\u5B9F\u969B\u306B\u4F7F\u308F\u308C\u3066\u3044\u308B\u30CF\u30C3\u30B7\u30E5\u30BF\u30B0\u3001\u30D5\u30A9\u30ED\u30FC\u3057\u305F\u3044\u4EBA\u3001\u5B87\u5B99\u597D\u304D\u304C\u96C6\u307E\u308B\u30B5\u30FC\u30D0\u30FC\u3092\u307E\u3068\u3081\u3066\u7D39\u4ECB\u3057\u307E\u3059\u3002"],faq:[{q:"\u8AAD\u3080\u306E\u306B\u30A2\u30AB\u30A6\u30F3\u30C8\u306F\u5FC5\u8981\u3067\u3059\u304B\uFF1F",a:"\u3044\u3044\u3048\u3002\u3053\u306E\u30DA\u30FC\u30B8\u306E\u30CF\u30C3\u30B7\u30E5\u30BF\u30B0\u306F\u3001\u30A2\u30AB\u30A6\u30F3\u30C8\u304C\u306A\u304F\u3066\u3082 Mawkingbird \u3067\u958B\u3051\u307E\u3059\u3002\u4EBA\u3084\u30BF\u30B0\u3092\u30D5\u30A9\u30ED\u30FC\u3059\u308B\u306B\u306F\u3001\u3069\u3053\u304B\u306E\u30B5\u30FC\u30D0\u30FC\u306B Mastodon \u306E\u30A2\u30AB\u30A6\u30F3\u30C8\u304C\u5FC5\u8981\u3067\u3059\u3002\u6700\u521D\u306F mastodon.social \u3067\u5341\u5206\u3067\u3001\u3042\u3068\u304B\u3089\u30D5\u30A9\u30ED\u30EF\u30FC\u3092\u9023\u308C\u3066\u5F15\u3063\u8D8A\u305B\u307E\u3059\u3002"},{q:"\u306A\u305C\u82F1\u8A9E\u306E\u30CF\u30C3\u30B7\u30E5\u30BF\u30B0\u304C\u3042\u308B\u306E\u3067\u3059\u304B\uFF1F",a:"Mastodon \u3067\u306F\u5929\u6587\u3084\u5B87\u5B99\u306E\u8A71\u984C\u306E\u591A\u304F\u304C\u82F1\u8A9E\u306E\u30CF\u30C3\u30B7\u30E5\u30BF\u30B0\u3067\u4EA4\u308F\u3055\u308C\u3066\u3044\u307E\u3059\u3002\u3044\u3061\u3070\u3093\u6D3B\u767A\u306A\u82F1\u8A9E\u306E\u30BF\u30B0\u3068\u3001#\u5B87\u5B99 \u306A\u3069\u3053\u308C\u304B\u3089\u80B2\u3066\u305F\u3044\u65E5\u672C\u8A9E\u306E\u30BF\u30B0\u3092\u4E00\u7DD2\u306B\u7D39\u4ECB\u3057\u3066\u3044\u307E\u3059\u3002"},{q:"\u3053\u306E\u30EA\u30B9\u30C8\u306B\u8F09\u308B\u306B\u306F\uFF1F",a:"\u5B87\u5B99\u3084\u5929\u6587\u306B\u3064\u3044\u3066\u6295\u7A3F\u3057\u3001\u4E0A\u306E\u30CF\u30C3\u30B7\u30E5\u30BF\u30B0\u3092\u4F7F\u3044\u3001\u30B5\u30FC\u30D0\u30FC\u306E\u30D7\u30E9\u30A4\u30D0\u30B7\u30FC\u8A2D\u5B9A\u3067\u30D7\u30ED\u30D5\u30A3\u30FC\u30EB\u3092\u304A\u3059\u3059\u3081\u306B\u8868\u793A\u3067\u304D\u308B\u3088\u3046\u306B\u3057\u3066\u304F\u3060\u3055\u3044\u3002\u30EA\u30B9\u30C8\u306F\u6BCE\u6708\u66F4\u65B0\u3055\u308C\u307E\u3059\u3002"}]}};export{e as COPY};
